<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {Phone,Plus,RefreshCw,Settings2,ShieldCheck,Server} from 'lucide-vue-next'
import DialogShell from './DialogShell.vue'
const state=ref(null),error=ref(''),notice=ref(''),busy=ref(false),form=ref(null),restricted=ref(false)
let timer
const labels={registered:'Registrado na operadora',pending:'Aplicando configuração',rejected:'Registro recusado',unregistered:'Sem registro',stale:'Verificação atrasada',disabled:'Conexão desativada',error:'Revisar conexão',no_policy:'Definir limites de chamadas'}
async function api(method='GET',data){const r=await fetch('/api/voice/providers',{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},...(data?{body:JSON.stringify(data)}:{}),signal:AbortSignal.timeout(15000)});const j=await r.json();if(!r.ok){if(r.status===403)restricted.value=true;throw new Error(Object.values(j.errors||{}).flat().join(' ')||j.message||'Não foi possível atualizar a conexão.')}return j}
async function refresh(silent=false){try{state.value=await api();if(!silent)error.value=''}catch(e){if(!silent)error.value=e.message}}
function defaults(provider){return provider==='fale_vono'?{id:crypto.randomUUID(),provider,label:'',number:'',host:'vono2.me',username:'',password:'',port:5060,transport:'udp',dial_format:'digits',concurrency:1,cps:1,enabled:true}:{provider:'twilio',account_sid:'',api_key:'',api_secret:'',auth_token:'',application_sid:'',caller_id:'',edge:'sao-paulo',enabled:false}}
function create(){error.value='';form.value=defaults('fale_vono')}
function changeProvider(){form.value=defaults(form.value.provider)}
function edit(c){error.value='';form.value=c.provider==='fale_vono'?{...c,password:'',editing:true}:{...defaults('twilio'),...c,editing:true}}
function number(v){let n=String(v||'').replace(/\D/g,'');if(n.length===10||n.length===11)n='55'+n;return '+'+n}
async function save(){busy.value=true;error.value='';try{const d={...form.value};if(d.provider==='fale_vono')d.number=number(d.number);else d.caller_id=number(d.caller_id);await api('PUT',d);form.value=null;notice.value=d.provider==='fale_vono'?'Conexão salva. O registro na operadora será atualizado automaticamente.':'Configuração Twilio salva.';await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>{refresh();timer=setInterval(()=>refresh(true),15000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
<section class="provider-panel">
 <div class="provider-heading"><div><span class="eyebrow">CONEXÕES DE VOZ</span><h2>Seus números, suas operadoras</h2><p>Configure a telefonia aqui e escolha o número nas filas de atendimento.</p></div><div class="provider-actions"><button class="secondary" @click="refresh()"><RefreshCw :size="16"/>Atualizar</button><button v-if="!restricted" class="primary" @click="create"><Plus :size="16"/>Configurar número</button></div></div>
 <p v-if="error&&!form&&!restricted" class="error" role="alert">{{error}}</p><p v-if="notice" class="provider-notice" role="status">{{notice}}</p>
 <article v-if="restricted" class="table-card provider-card"><ShieldCheck :size="25"/><h3>Telefonia gerenciada pela DiscAI</h3><p>A administração DiscAI configura as operadoras. Os números liberados podem ser selecionados nas suas filas.</p></article>
 <template v-else-if="state">
 <div class="provider-grid">
  <article v-if="state.twilio" class="table-card provider-card"><div class="provider-top"><span class="provider-icon"><Phone :size="22"/></span><span class="status" :class="state.twilio.enabled?'active':'paused'">{{state.twilio.enabled?'API habilitada':'API desativada'}}</span></div><span class="eyebrow">TWILIO · API DE VOZ</span><h3>{{state.twilio.caller_id}}</h3><p>Conexão de voz pelo navegador.</p><button v-if="!state.twilio.managed_by_portal" class="secondary" @click="edit({...state.twilio,provider:'twilio'})"><Settings2 :size="16"/>Configurar</button><p v-else class="small">Conexão gerenciada em Números e solicitações.</p></article>
  <article v-for="c in state.sip" :key="c.id" class="table-card provider-card"><div class="provider-top"><span class="provider-icon"><Server :size="22"/></span><span class="status" :class="c.ready?'active':'paused'">{{labels[c.registration_state]||'Aguardando verificação'}}</span></div><span class="eyebrow">FALE VONO · SIP TRUNK</span><h3>{{c.label}}</h3><p class="provider-number">{{c.number}}</p><div class="provider-metrics"><span><strong>{{c.concurrency}}</strong> {{c.concurrency===1?'canal':'canais'}}</span><span><strong>{{c.cps}}</strong> {{c.cps===1?'tentativa/s':'tentativas/s'}}</span></div><p>{{c.ready?'Disponível para saída nas filas que selecionarem este número.':!state.policy_configured?'A conexão aguarda a definição dos limites de homologação.':'O registro confirma a conexão. Áudio e identificação precisam de uma chamada de homologação.'}}</p><button class="secondary" @click="edit(c)"><Settings2 :size="16"/>Configurar</button></article>
  <button class="provider-add" @click="create"><Plus :size="25"/><strong>Adicionar número</strong><span>Escolha Twilio ou Fale Vono</span></button>
 </div>
 <p class="provider-footnote"><ShieldCheck :size="16"/>Credenciais protegidas no servidor. Salvar não inicia chamadas nem ativa campanhas.</p>
 </template>
 <DialogShell v-if="form" title="Configurar número de voz" description="Escolha a operadora e informe os dados da conexão." :busy="busy" :draft="form" @close="form=null;error=''">
  <form id="provider-form" class="provider-form" @submit.prevent="save">
   <p v-if="error" class="error" role="alert">{{error}}</p>
   <label>Operadora<select aria-label="Operadora" v-model="form.provider" :disabled="form.editing" @change="changeProvider"><option value="twilio">Twilio · API de voz</option><option value="fale_vono">Fale Vono · SIP Trunk</option></select></label>
   <template v-if="form.provider==='fale_vono'">
    <div class="provider-form-row"><label>Nome da conexão<input v-model="form.label" required maxlength="100" placeholder="Ex.: Comercial · DDD 11"></label><label>Número de saída (bina)<input v-model="form.number" type="tel" required placeholder="(11) 3000-1234"></label></div>
    <fieldset><legend>Acesso fornecido pela Fale Vono</legend><label>Domínio / servidor<input v-model="form.host" required placeholder="vono2.me"></label><div class="provider-form-row"><label>Usuário SIP<input v-model="form.username" autocomplete="off" required maxlength="64"></label><label>Senha SIP<input v-model="form.password" type="password" autocomplete="new-password" :required="!form.password_saved" :placeholder="form.password_saved?'Deixe vazio para manter':'Senha da operadora'" maxlength="128"></label></div></fieldset>
    <details><summary>Capacidade e formato de discagem</summary><div class="provider-form-row"><label>Canais simultâneos contratados<input v-model.number="form.concurrency" type="number" min="1" max="100" required></label><label>Máximo de tentativas por segundo<input v-model.number="form.cps" type="number" min="1" max="10" required></label></div><label>Formato enviado à operadora<select aria-label="Formato enviado à operadora" v-model="form.dial_format"><option value="digits">55 + DDD + número · padrão Fale Vono</option><option value="national">DDD + número · somente se indicado pela operadora</option><option value="e164">Internacional com + · +551130001234</option></select></label><p>O limite efetivo também respeita a capacidade do servidor e das filas. Confirme com a Vono os canais contratados e a permissão para uso preditivo.</p><p>SIP: UDP / porta 5060. Esta conexão configura chamadas de saída; o recebimento por SIP exige uma rota receptiva própria.</p></details>
    <label class="check"><input v-model="form.enabled" type="checkbox">Manter conexão SIP habilitada</label>
   </template>
   <template v-else>
    <label>Número de saída<input v-model="form.caller_id" type="tel" required placeholder="+551130001234"></label>
    <fieldset><legend>Conta Twilio</legend><label>Account SID<input v-model="form.account_sid" required placeholder="AC…"></label><label>Auth Token<input v-model="form.auth_token" type="password" autocomplete="new-password" :required="!form.editing" :placeholder="form.editing?'Deixe vazio para manter':'Auth Token'"></label><label>API Key SID<input v-model="form.api_key" required placeholder="SK…"></label><label>API Key Secret<input v-model="form.api_secret" type="password" autocomplete="new-password" :required="!form.editing" :placeholder="form.editing?'Deixe vazio para manter':'API Key Secret'"></label><label>TwiML Application SID<input v-model="form.application_sid" required placeholder="AP…"></label></fieldset>
    <label class="check"><input v-model="form.enabled" type="checkbox">Habilitar esta conexão de voz</label><p>Use um número autorizado na conta Twilio. As filas e os limites de chamadas continuam valendo.</p>
   </template>
  </form>
  <template #footer="{close}"><button type="button" class="secondary" :disabled="busy" @click="close">Cancelar</button><button class="primary" form="provider-form" type="submit" :disabled="busy">{{busy?'Salvando…':'Salvar conexão'}}</button></template>
 </DialogShell>
</section>
</template>
<style scoped>
.provider-heading{display:flex;justify-content:space-between;gap:24px;align-items:center;margin:26px 0}.provider-heading h2{margin:10px 0}.provider-actions,.provider-top,.provider-metrics{display:flex;gap:12px;align-items:center}.provider-top{justify-content:space-between;margin-bottom:24px}.provider-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}.provider-card{padding:26px;border-radius:20px;box-shadow:0 8px 28px #25382d08;display:flex;flex-direction:column;align-items:flex-start;gap:10px}.provider-top{width:100%}.provider-icon{padding:12px;background:#f8f1df;color:#b18a29;border-radius:14px}.provider-card h3{margin:0}.provider-card p,.provider-heading p,.provider-form p{color:#75806d;line-height:1.6;margin:4px 0 12px}.provider-card button{margin-top:auto}.provider-number{font-size:18px;letter-spacing:.4px}.provider-metrics span{padding:10px 14px;background:#f5f6f0;border-radius:10px;font-size:12px}.provider-metrics strong{font-size:17px;margin-right:5px}.provider-add{min-height:260px;border:1px dashed #d2d8c6;border-radius:20px;background:#fafbf7;color:#71816a;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:13px}.provider-add:hover{background:#f6f0e2;border-color:#c99b38}.provider-footnote{display:flex;align-items:center;gap:9px;color:#75806d;font-size:12px;margin:22px 0}.provider-notice{padding:16px 20px;border-radius:12px;background:#eaf3e5;color:#395d3d}.provider-form{display:grid;gap:20px}.provider-form label{display:grid;gap:8px;font-weight:600;font-size:13px}.provider-form .check{display:flex;align-items:center}.provider-form fieldset{border:1px solid #e1e5da;border-radius:14px;padding:18px;display:grid;gap:16px;min-width:0}.provider-form legend{padding:0 7px;color:#78836a;font-size:12px}.provider-form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.provider-form details{padding:17px;border:1px solid #e1e5da;border-radius:12px}.provider-form summary{cursor:pointer;font-weight:600}.provider-form details[open]>summary{margin-bottom:20px}.provider-form details>label,.provider-form details>p{margin-top:16px}@media(max-width:650px){.provider-heading{align-items:flex-start;flex-direction:column}.provider-form-row{grid-template-columns:1fr}.provider-actions{flex-wrap:wrap}}
</style>
